<script>
const operationType = document.getElementById('type');
const operationAmount = document.getElementById('amount');
const companyField = document.getElementById('company-field');
const companySelect = document.getElementById('company');
const beneficiaryField = document.getElementById('beneficiary-field');
const beneficiaryInput = document.getElementById('beneficiary');
const normalMaximum = '9999999999.99';
const availableMaximum = operationAmount?.dataset.available ?? '0.00';
const updateAmountMaximum = () => {
    const isExpense = operationType ? operationType.value === 'depense' : @json($page === 'expenses');
    if (operationAmount) operationAmount.max = isExpense ? availableMaximum : normalMaximum;
    if (companyField) companyField.classList.toggle('d-none', !isExpense);
    if (companySelect) {
        companySelect.required = isExpense;
        if (!isExpense) companySelect.value = '';
    }
    if (beneficiaryField) beneficiaryField.classList.toggle('d-none', !isExpense);
    if (beneficiaryInput) {
        beneficiaryInput.required = isExpense;
        if (!isExpense) beneficiaryInput.value = '';
    }
};
operationType?.addEventListener('change', updateAmountMaximum);
updateAmountMaximum();
@if($errors->has('amount') || $errors->has('description') || $errors->has('occurred_on') || $errors->has('payment_method') || $errors->has('type') || $errors->has('company') || $errors->has('beneficiary') || $errors->has('justification'))
new bootstrap.Modal(document.getElementById('operationModal')).show();
@endif
</script>
@endif
